style.css:
@-moz-document domain("roblox.com") {
/* Cambia el fondo con tu imagen */
  body {
    background: url("https://i.ibb.co/4NpYkHF/fondo.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #ffffff !important;
    font-family: 'Verdana', sans-serif !important;
  }

  /* Personaliza el texto */
  p, span, div, a, h1, h2, h3 {
    color: #ffccff !important; /* Texto con un tono glam */
    text-shadow: 2px 2px 4px #660099 !important;
  }

  /* Cambia los botones */
  button {
    background: linear-gradient(to right, #ff66cc, #660099) !important;
    border: 2px solid #ffffff !important;
    border-radius: 12px !important;
    color: #ffffff !important;
    font-weight: bold !important;
    transition: transform 0.3s ease, box-shadow 0.3s ease;
  }

  button:hover {
    transform: scale(1.1);
    box-shadow: 0px 5px 20px rgba(255, 102, 204, 0.8);
  }

  /* Bordes a los cuadros */
  .container, .card, .popup {
    border: 2px solid #ff66cc !important;
    box-shadow: 0px 4px 15px rgba(0, 0, 0, 0.5) !important;
  }
}
